pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0) && _tos[i] != from);
        }
        // Record balances before transfer
        uint[] memory beforeBal = new uint[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            beforeBal[i] = _tos[i].balance;
        }
        uint fromBefore = from.balance;
        // Call transfer
        bool success = c.transfer(from, caddress, _tos, v);
        // After call, check that sum of recipient balance increases equals total transferred (if success)
        uint totalTransferred = 0;
        for (uint i = 0; i < _tos.length; i++) {
            totalTransferred += v[i];
        }
        uint sumDelta = 0;
        for (uint i = 0; i < _tos.length; i++) {
            sumDelta += _tos[i].balance - beforeBal[i];
        }
        assertTrue(!success || sumDelta == totalTransferred);
    }
}

